package com.kellvyn.assistant.workspace

import android.content.Context
import android.net.Uri
import org.json.JSONArray
import org.json.JSONObject
import java.io.BufferedOutputStream
import java.io.File
import java.util.Locale
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

data class WorkspaceProject(
    val id: String,
    val name: String,
    val description: String,
    val fileCount: Int,
    val updatedAt: Long
)

data class ProjectFileInput(
    val path: String,
    val content: String
)

/**
 * Local-only workspace for text files generated by the AI builder.
 *
 * Generated files are stored as data and are never executed by this class.
 * Paths and sizes are validated before writing to prevent traversal and runaway output.
 */
class ProjectWorkspaceStore(context: Context) {
    private val resolverContext = context.applicationContext
    private val root = File(resolverContext.filesDir, "kellvyn_projects")

    fun listProjects(): List<WorkspaceProject> {
        if (!root.isDirectory) return emptyList()
        return root.listFiles()?.filter { it.isDirectory }?.mapNotNull { directory ->
            readProject(directory.name)
        }?.sortedByDescending { it.updatedAt }.orEmpty()
    }

    fun getProject(projectId: String): WorkspaceProject? = readProject(projectId)

    @Synchronized
    fun createProject(name: String, description: String, files: List<ProjectFileInput>): WorkspaceProject {
        val cleanName = name.trim().take(MAX_NAME_CHARS).ifBlank { "Projeto Kellvyn" }
        val cleanDescription = description.trim().take(MAX_DESCRIPTION_CHARS)
        validateFiles(files)

        if (!root.exists() && !root.mkdirs()) {
            throw IllegalStateException("Não foi possível criar a pasta privada de projetos.")
        }

        val base = slugify(cleanName)
        var id = base
        var suffix = 2
        while (File(root, id).exists()) {
            id = "$base-$suffix"
            suffix++
        }

        val directory = File(root, id)
        if (!directory.mkdirs()) throw IllegalStateException("Não foi possível criar a pasta do projeto.")
        try {
            writeProjectFiles(directory, files)
            val metadata = JSONObject()
                .put("id", id)
                .put("name", cleanName)
                .put("description", cleanDescription)
                .put("updatedAt", System.currentTimeMillis())
            File(directory, PROJECT_METADATA).writeText(metadata.toString(), Charsets.UTF_8)
            return WorkspaceProject(id, cleanName, cleanDescription, files.size, metadata.getLong("updatedAt"))
        } catch (e: Exception) {
            directory.deleteRecursively()
            throw e
        }
    }

    @Synchronized
    fun addOrReplaceFiles(projectId: String, files: List<ProjectFileInput>): WorkspaceProject {
        validateProjectId(projectId)
        val directory = File(root, projectId)
        val project = readProject(projectId) ?: throw IllegalArgumentException("Projeto não encontrado.")
        validateFiles(files)
        writeProjectFiles(directory, files)
        val metadata = JSONObject()
            .put("id", project.id)
            .put("name", project.name)
            .put("description", project.description)
            .put("updatedAt", System.currentTimeMillis())
        File(directory, PROJECT_METADATA).writeText(metadata.toString(), Charsets.UTF_8)
        return readProject(projectId) ?: project.copy(updatedAt = System.currentTimeMillis())
    }

    fun readFile(projectId: String, relativePath: String): String {
        validateProjectId(projectId)
        val directory = File(root, projectId)
        val projectFile = safeFile(directory, relativePath)
        require(projectFile.isFile) { "Arquivo não encontrado: $relativePath" }
        return projectFile.readText(Charsets.UTF_8)
    }

    fun listFiles(projectId: String): List<String> {
        validateProjectId(projectId)
        val directory = File(root, projectId)
        require(readProject(projectId) != null) { "Projeto não encontrado." }
        return directory.walkTopDown()
            .filter { it.isFile && it.name != PROJECT_METADATA }
            .map { it.relativeTo(directory).invariantSeparatorsPath }
            .sorted()
            .toList()
    }

    fun deleteProject(projectId: String) {
        validateProjectId(projectId)
        val directory = File(root, projectId)
        if (directory.exists() && !directory.deleteRecursively()) {
            throw IllegalStateException("Não foi possível apagar o projeto.")
        }
    }

    fun exportZip(projectId: String, destination: Uri) {
        validateProjectId(projectId)
        val directory = File(root, projectId)
        val project = readProject(projectId) ?: throw IllegalArgumentException("Projeto não encontrado.")
        val files = listFiles(projectId)
        require(files.isNotEmpty()) { "O projeto ainda não contém arquivos." }

        val output = resolverContext.contentResolver.openOutputStream(destination, "w")
            ?: throw IllegalStateException("O Android não conseguiu abrir o destino do ZIP.")
        ZipOutputStream(BufferedOutputStream(output)).use { zip ->
            val rootReadme = buildString {
                appendLine("# ${project.name}")
                appendLine()
                if (project.description.isNotBlank()) appendLine(project.description)
                appendLine()
                appendLine("Gerado pelo Kellvyn IA. Revise e teste o código antes de executar.")
            }
            zip.putNextEntry(ZipEntry("KELLVYN_PROJECT.md"))
            zip.write(rootReadme.toByteArray(Charsets.UTF_8))
            zip.closeEntry()

            for (relativePath in files) {
                val file = safeFile(directory, relativePath)
                if (!file.isFile) continue
                zip.putNextEntry(ZipEntry(relativePath))
                file.inputStream().use { input -> input.copyTo(zip) }
                zip.closeEntry()
            }
        }
    }

    private fun readProject(projectId: String): WorkspaceProject? {
        if (!isValidProjectId(projectId)) return null
        val directory = File(root, projectId)
        val metadataFile = File(directory, PROJECT_METADATA)
        if (!metadataFile.isFile) return null
        return try {
            val json = JSONObject(metadataFile.readText(Charsets.UTF_8))
            val files = listFilesWithoutMetadata(directory).size
            val storedId = json.getString("id")
            if (storedId != projectId) return null
            WorkspaceProject(
                id = storedId,
                name = json.getString("name"),
                description = json.optString("description"),
                fileCount = files,
                updatedAt = json.optLong("updatedAt", directory.lastModified())
            )
        } catch (_: Exception) {
            null
        }
    }

    private fun listFilesWithoutMetadata(directory: File): List<File> =
        directory.walkTopDown().filter { it.isFile && it.name != PROJECT_METADATA }.toList()

    private fun writeProjectFiles(directory: File, files: List<ProjectFileInput>) {
        files.forEach { item ->
            val target = safeFile(directory, item.path)
            val parent = target.parentFile ?: throw IllegalArgumentException("Caminho de arquivo inválido.")
            if (!parent.exists() && !parent.mkdirs()) {
                throw IllegalStateException("Não foi possível criar a pasta para ${item.path}.")
            }
            val temporary = File(parent, target.name + ".kellvyn-tmp")
            temporary.writeText(item.content, Charsets.UTF_8)
            if (target.exists() && !target.delete()) {
                temporary.delete()
                throw IllegalStateException("Não foi possível substituir ${item.path}.")
            }
            if (!temporary.renameTo(target)) {
                temporary.delete()
                throw IllegalStateException("Não foi possível gravar ${item.path}.")
            }
        }
    }

    private fun validateFiles(files: List<ProjectFileInput>) {
        require(files.isNotEmpty()) { "O construtor não gerou arquivos." }
        require(files.size <= MAX_FILES) { "O projeto excede o limite de $MAX_FILES arquivos." }
        val seen = HashSet<String>()
        var totalBytes = 0L
        files.forEach { file ->
            val path = normalizeRelativePath(file.path)
            require(seen.add(path.lowercase(Locale.ROOT))) { "Caminho duplicado no projeto: $path" }
            val bytes = file.content.toByteArray(Charsets.UTF_8).size
            require(bytes <= MAX_FILE_BYTES) { "O arquivo $path excede o limite de tamanho." }
            totalBytes += bytes
        }
        require(totalBytes <= MAX_PROJECT_BYTES) { "O projeto excede o limite de tamanho total." }
    }

    private fun safeFile(directory: File, path: String): File {
        val normalized = normalizeRelativePath(path)
        val rootCanonical = directory.canonicalFile
        val target = File(rootCanonical, normalized).canonicalFile
        require(target.path.startsWith(rootCanonical.path + File.separator)) {
            "O caminho do arquivo sai da pasta do projeto."
        }
        return target
    }

    private fun normalizeRelativePath(input: String): String {
        val path = input.trim()
        require(path.isNotBlank()) { "O caminho de arquivo está vazio." }
        require(!path.startsWith("/") && !path.startsWith("\\") && !path.contains("\\")) {
            "Use um caminho relativo com barras normais."
        }
        val segments = path.split("/")
        require(segments.all { it.isNotBlank() && it != "." && it != ".." }) {
            "O caminho contém um segmento inválido."
        }
        require(segments.none { it.contains(":") || it.any { char -> char.code < 32 } }) {
            "O caminho contém caracteres não permitidos."
        }
        require(segments.none {
            it.equals(".git", true) ||
                it.equals(".gradle", true) ||
                it.equals(PROJECT_METADATA, true)
        }) {
            "O construtor não pode gravar metadados internos do projeto, Git ou Gradle."
        }
        require(segments.size != 1 || !segments[0].equals("KELLVYN_PROJECT.md", true)) {
            "O nome KELLVYN_PROJECT.md é reservado para o pacote de exportação."
        }
        require(path.toByteArray(Charsets.UTF_8).size <= MAX_PATH_BYTES) { "O caminho do arquivo é muito longo." }
        return segments.joinToString("/")
    }

    private fun slugify(value: String): String {
        val slug = value.lowercase(Locale.ROOT)
            .replace(Regex("[^a-z0-9]+"), "-")
            .trim('-')
            .take(40)
        return slug.ifBlank { "projeto-kellvyn" }
    }

    private fun validateProjectId(projectId: String) {
        require(isValidProjectId(projectId)) { "Identificador de projeto inválido." }
    }

    private fun isValidProjectId(projectId: String): Boolean =
        projectId.matches(Regex("[a-z0-9][a-z0-9-]{0,60}"))

    private companion object {
        const val PROJECT_METADATA = ".kellvyn-project.json"
        const val MAX_NAME_CHARS = 80
        const val MAX_DESCRIPTION_CHARS = 2_000
        const val MAX_FILES = 150
        const val MAX_FILE_BYTES = 512 * 1024
        const val MAX_PROJECT_BYTES = 5L * 1024 * 1024
        const val MAX_PATH_BYTES = 240
    }
}
